function render({ detail, state, workflow, baseUrl }) {
  if (detail) {
    const w = workflow,
      nodes = w.nodes.filter((x) => x.type !== "n8n-nodes-base.stickyNote"),
      ids = new Map(nodes.map((x, i) => [x.name, "N" + i])),
      labels = new Map(
        nodes.map((x) => [
          x.name,
          String(x.name ?? "").replace(/[^\w\s-]/g, (c) => "#" + c.codePointAt(0) + ";"),
        ]),
      ),
      byName = new Map(nodes.map((x) => [x.name, x])),
      shape = (name) => {
        const id = ids.get(name),
          label = '\"' + labels.get(name) + '\"',
          type = byName.get(name)?.type;
        return type === "n8n-nodes-base.if" || type === "n8n-nodes-base.switch"
          ? id + "{" + label + "}"
          : type === "n8n-nodes-base.code" || type === "n8n-nodes-base.executeWorkflow"
            ? id + "[[" + label + "]]"
            : type === "n8n-nodes-base.wait"
              ? id + "(" + label + ")"
              : id + "[" + label + "]";
      },
      lines = [],
      used = new Set();
    for (const [from, groups] of Object.entries(w.connections ?? {})) {
      if (!ids.has(from)) continue;
      for (const [kind, outs] of Object.entries(groups ?? {}))
        for (const edges of outs ?? [])
          for (const e of edges ?? []) {
            if (!ids.has(e.node)) continue;
            lines.push(
              shape(from) +
                " " +
                (kind === "main" ? "-->" : "-.->|" + String(kind).replace(/[^\w-]/g, "") + "|") +
                " " +
                shape(e.node),
            );
            used.add(from);
            used.add(e.node);
          }
    }
    for (const n of nodes) if (!used.has(n.name)) lines.push(shape(n.name));
    for (const n of nodes) if (n.disabled) lines.push("class " + ids.get(n.name) + " disabled");
    if (nodes.some((n) => n.disabled))
      lines.push("classDef disabled stroke-dasharray: 5 5,opacity:0.5");
    return { body: "flowchart LR\n" + lines.join("\n"), contentType: "text/plain; charset=utf-8" };
  }
  if (typeof baseUrl !== "string" || !/^https:\/\//.test(baseUrl) || baseUrl.includes("YOUR_"))
    throw Error("Configure n8n instance URL");
  const base = JSON.stringify(baseUrl.replace(/\/+$/, ""))
    .replace(/</g, "\\u003c")
    .replace(/&/g, "\\u0026");
  const data = JSON.stringify(state.items).replace(/</g, "\\u003c").replace(/&/g, "\\u0026");
  return {
    body: `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>n8n workflows</title><script src="https://cdn.jsdelivr.net/npm/mermaid/dist/mermaid.min.js"></script><style>body{font:16px system-ui;max-width:960px;margin:3rem auto;padding:0 1rem}article{border:1px solid #ddd;border-radius:8px;margin:1rem 0;padding:1rem}button{padding:.5rem}</style></head><body><h1>n8n workflows</h1><main id="workflows"></main><script>const workflows=${data},instanceUrl=${base};mermaid.initialize({startOnLoad:false,securityLevel:'strict'});const root=document.getElementById('workflows');for(const workflow of workflows){const card=document.createElement('article'),title=document.createElement('h2'),link=document.createElement('a'),button=document.createElement('button'),diagram=document.createElement('div');link.textContent=workflow.name;link.href=instanceUrl+'/workflow/'+encodeURIComponent(workflow.id);link.target='_blank';link.rel='noopener noreferrer';title.append(link);button.textContent='Show workflow';button.onclick=async()=>{if(diagram.dataset.loaded){diagram.hidden=!diagram.hidden;return}const url=new URL(location.href);url.search='';url.searchParams.set('wfid',workflow.id);const r=await fetch(url);if(!r.ok){diagram.textContent='Unable to load workflow';return}diagram.className='mermaid';diagram.textContent=await r.text();await mermaid.run({nodes:[diagram]});diagram.dataset.loaded='1'};card.append(title,button,diagram);root.append(card)}</script></body></html>`,
    contentType: "text/html; charset=utf-8",
  };
}

return [
  {
    json: render({
